questions.questionText:
What will be the output of the following C++ code snippet?
#include <iostream>
using namespace std;
int main() {
int a = 5;
cout << (a++ + ++a);
return 0;
}

What will be the output of the following C++ code?
#include <iostream>
using namespace std;
int main() {
int x = 10, y = 20;
int &ref = x;
ref = y;
cout << x << " " << ref;
return 0;
}

What will be the output of the following C++ code?
#include <iostream>
using namespace std;
void fun(int x = 10, int y = 20) {
cout << x + y;
}
int main() {
fun(5);
return 0;
}
